              "https://img.youtube.com/"
            ]
            for (var i = 0; i < allowedHosts.length; i++) {
              if (src.indexOf(allowedHosts[i]) === 0) return src
            }
            return ""
          }
          if (src.indexOf("http") === 0) return ""
          return root._readmeBaseUrl + src
        }

